def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def check_divisibility(n):
    divisor = D(n)
    if divisor == 0:
        return False, "Divisor is zero"

    numerator = 20**(n+1)

    if numerator % divisor == 0:
        return True, divisor
    else:
        return False, divisor

solutions = []
for n in range(11): # Test n = 0 to 10
    is_solution, divisor_value = check_divisibility(n)
    solutions.append((n, is_solution, divisor_value))

for n, is_solution, divisor_value in solutions:
    status = "Solution" if is_solution else "Not a solution"
    print(f"n={n}: D(n) = {divisor_value}, Divisibility check: {status}")

print("\nSummary of solutions:")
for n, is_solution, divisor_value in solutions:
    if is_solution:
        print(f"n={n} is a solution, D(n) = {divisor_value}")

def D(n):
    return n**3 + 4*n**2 + 6*n + 4

def is_2_or_5_factor(k):
    if k == 0:
        return False 
    k = abs(k)
    if k == 1:
        return True

    while k % 2 == 0:
        k //= 2
    while k % 5 == 0:
        k //= 5
    return k == 1

def check_divisibility(n):
    d_n = D(n)
    if not is_2_or_5_factor(d_n):
        return False

    # Factor d_n = 2^a * 5^b
    temp_d = d_n
    a = 0
    b = 0
    while temp_d % 2 == 0:
        a += 1
        temp_d //= 2
    while temp_d % 5 == 0:
        b += 1
        temp_d //= 5

    # Check exponents: d_n | 20^(n+1) = 2^(2n+2) * 5^(n+1)
    required_2 = 2*n + 2
    required_5 = n + 1

    if a > required_2 or b > required_5:
        return False

    return True

solutions = []
for n in range(51):
    if check_divisibility(n):
        solutions.append(n)

print("Solutions found up to n=50:", solutions)
